CustomField.formula:
IF( ISPICKVAL( Project_Health__c , "Red - Significant Obstacles or Problems"), IMAGE("/img/msg_icons/error16.png", "Red"), IF( ISPICKVAL( Project_Health__c , "Yellow - Raise Concern"), IMAGE("/img/msg_icons/warning16.png", "Yellow"), IF( ISPICKVAL( Project_Health__c , "Green - No Issues"), IMAGE("/img/msg_icons/confirm16.png", "Green"),
"")
) )
